function data=clv_data(sys,K,cfg,groups,seed,noiseStd)
% Independent repetitions start from zero; burn-in precedes one saved period.
% d/u/y are generated by sample-domain lsim, never by injecting FRF noise.
rng(seed,'twister');N=cfg.period_samples;burn=cfg.burn_samples;Nt=burn+N;
f=cfg.frequencies_hz(:);nf=numel(f);bins=round(f/cfg.Fs*N)+1;
assert(all(abs((bins-1)*cfg.Fs/N-f)<1e-12));
phase=2*pi*rand(4,nf);amp=cfg.force_peak_per_line*exp(1i*phase);
D=complex(zeros(4,4,nf));Y=complex(zeros(16,nf,groups));U=Y;V=Y;
t=(0:Nt-1)'/cfg.Fs; keep=burn+(1:N); example=struct; timeIdentity=0;
saveRaw=isfield(cfg,'save_raw')&&cfg.save_raw;raw=cell(4,groups);cleanFull=cell(4,1);cleanU=cell(4,1);
for input=1:4
    spec=zeros(4,N);spec(input,bins)=N/2*amp(input,:);spec(input,N-bins+2)=N/2*conj(amp(input,:));
    period=real(ifft(spec,[],2)).';d=repmat(period,ceil(Nt/N),1);d=d(1:Nt,:);
    Da=(2/N)*fft(d(keep,:),[],1);Da=Da(bins,:).';D(:,input,:)=reshape(Da,4,1,nf);
    if saveRaw
        clean=lsim(sys,[d zeros(Nt,4)],t);cleanFull{input}=clean(:,1:4);cleanU{input}=clean(:,5:8);
    end
    for r=1:groups
        v=noiseStd*randn(Nt,4);out=lsim(sys,[d v],t); yy=out(keep,1:4);uu=out(keep,5:8);
        fy=(2/N)*fft(yy,[],1);fu=(2/N)*fft(uu,[],1);fv=(2/N)*fft(v(keep,:),[],1);
        rows=(1:4)+4*(input-1);Y(rows,:,r)=fy(bins,:).';U(rows,:,r)=fu(bins,:).';V(rows,:,r)=fv(bins,:).';
        if saveRaw,raw{input,r}=out(:,1:4);end
        if r==1
            ky=lsim(K,out(:,1:4),t);err=out(keep,5:8)-d(keep,:)+ky(keep,:);
            timeIdentity=max(timeIdentity,norm(err,'fro')/max(norm(out(keep,5:8),'fro'),realmin));
        end
        if input==1&&r==1
            example=struct('time_seconds',(0:N-1)'/cfg.Fs,'d',d(keep,:),'u',uu,'y',yy,'sensor_noise',v(keep,:));
        end
    end
end
Kf=freqresp(K,2*pi*f);identity=0;
for r=1:groups
    e=reshape(U(:,:,r),4,4,nf)-D+pagemtimes(Kf,reshape(Y(:,:,r),4,4,nf));
    identity=max(identity,norm(e(:))/max(norm(U(:,:,r),'fro'),realmin));
end
noiseU=U-mean(U,3);noiseV=V-mean(V,3);
correlation=abs(sum(noiseU(:).*conj(noiseV(:))))/max(norm(noiseU(:))*norm(noiseV(:)),realmin);
data=struct('Y',Y,'U',U,'D',D,'V',V,'f',f,'mean',mean(Y,3),'groups',groups, ...
    'seed',seed,'sample_noise_std',noiseStd,'example',example,'time_command_identity_relative_error',timeIdentity, ...
    'finite_record_frequency_identity_relative_error',identity, ...
    'input_sensor_noise_complex_correlation',correlation);
if saveRaw,data.raw=raw;data.clean_full=cleanFull;data.clean_u=cleanU;data.time_full=t;end
end
